const GENERIC = 
  '<path d="M12 3.5l6.2 8.5L12 20.5 5.8 12z" />'

export function TechLogo({ logo, size = 16 }) {
  const paths = LOGOS[logo]
  const d = paths && paths[0]
  if (!d) {
    return (
      <svg
        className="tech-logo tech-logo-generic"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="currentColor"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
      >
        <path d={GENERIC} />
      </svg>
    )
  }
  return (
    <svg
      className="tech-logo"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path d={d} />
    </svg>
  )
}
